// Benachrichtigungen (ALLY 34, BA4b, Stefan 20.10.2026): alle Benachrichtigungen der angemeldeten Person (nur eigene), gelesen/ungelesen,
// Filter Art und Status, Tabelle sortierbar (Zeit, Art, Benachrichtigung; Sortierung je Person), 20 je Seite, Link zur Stelle.
// Daten: ally_benachrichtigungen_web (Migration 58). Ein Link mit bn=<id> markiert die eigene Benachrichtigung beim Öffnen als gelesen (ALLY 20 / ally_ui_eingang);
// "Alle als gelesen markieren" = Aktion benachrichtigungen_gelesen. Liefert nur die Seitenbeschreibung (JSON).
// BA10 (Migration 69): Abschnitt „Ergebnisse“ – vollständiger Text der letzten Morgen-Briefings, Kundenüberblicke und Wochen-Briefings (bisher nur im Chat lesbar),
// Lesen im Seitenfenster (er=<id>), PDF des Kundenüberblicks zum Herunterladen über Ally (Seite „datei“, er=<id>; Rechte prüft die Datenbank).
const E = $('Start').first().json;
const R = ($input.first().json || {}).r || {};
const F = E.funktion || {};
const titel = String(F.name || 'Benachrichtigungen');
const kopf = { schluessel: 'benachrichtigungen', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const zahnrad = /^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || '')) ? { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } : null;
if (zahnrad) kopf.zahnrad = { ziel: zahnrad, label: 'Einstellungen für Benachrichtigungen' };
if (R.ok !== true) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Die Benachrichtigungen konnten nicht geladen werden. Bitte die Seite neu laden.' }] } } }];
const zahl = n => Number(n || 0).toLocaleString('de-DE');
const FI = R.filter || {};
const fArt = String(FI.art || ''), fStatus = FI.status === 'ungelesen' ? 'ungelesen' : 'alle';
const filterParam = Object.assign({}, fArt ? { art: fArt } : {}, fStatus === 'ungelesen' ? { status: 'ungelesen' } : {});
const ungelesen = Number(R.ungelesen) || 0;
if (ungelesen > 0) kopf.hauptaktion = { text: 'Alle als gelesen markieren', aktion: 'benachrichtigungen_gelesen' };
const ueberblick = { kennzahlen: [
  { label: 'Ungelesen', wert: zahl(ungelesen), neben: ungelesen ? 'anzeigen' : 'alles gelesen', ton: ungelesen ? '' : 'grau', ziel: { seite: 'benachrichtigungen', parameter: { status: 'ungelesen' }, anker: 'a-alle' } },
  { label: 'Heute', wert: zahl(R.heute), neben: '' },
  { label: 'Letzte 7 Tage', wert: zahl(R.woche), neben: '' },
  { label: 'Insgesamt', wert: zahl(R.alle), neben: '', ziel: { seite: 'benachrichtigungen', anker: 'a-alle' } }] };
const ziel = z => z && typeof z === 'object' && /^[a-z0-9-]{1,40}$/.test(String(z.seite || '')) ? z : null;
// Layout 12 (Plan 39, Koordinator 24.10.2026, E8/E10): 10 je Seite wie die Anzeige – aus der Datenbank-Seite (20) die passende Hälfte; „Alle markieren“ = sichtbare Seite
const JE = 10;
const sW = Math.min(Math.max(1, Math.ceil((Number(R.gesamt) || 0) / JE)), Math.max(1, Number((E.seiten || {}).alle) || 1));
const halb = (Number(R.seite) || 1) === Math.ceil(sW / 2) ? (sW - 1) % 2 : 0;
const zeilen = (Array.isArray(R.zeilen) ? R.zeilen : []).slice(halb * JE, halb * JE + JE).map(b => {
  const neu = b.ungelesen === true, zi = ziel(b.ziel);
  const text = String(b.text || '');
  return { aktiv: neu, zellen: {
    zeit: String(b.zeit || ''),
    art: String(b.art_name || b.art || ''),
    titel: Object.assign({ text: String(b.titel || ''), fett: neu }, zi ? { ziel: zi } : {}, text ? { neben: text.length > 180 ? text.slice(0, 179) + '…' : text } : {}),
    status: { marke: neu ? { text: 'neu', ton: 'ok' } : { text: 'gelesen', ton: 'grau' } },
    aktion: neu && /^[0-9]{1,18}$/.test(String(b.id)) ? { aktion: { text: 'Als gelesen markieren', label: 'Als gelesen markieren: ' + String(b.titel || ''),
      ziel: { seite: 'benachrichtigungen', parameter: Object.assign({}, filterParam, { bn: String(b.id) }), anker: 'a-alle' } } } : ''
  } };
});
const arten = (Array.isArray(R.arten) ? R.arten : []).filter(a => /^[a-z0-9_]{1,40}$/.test(String(a.wert || ''))).map(a => ({ wert: String(a.wert), text: String(a.text || a.wert) }));
const so = R.sortierung || {};
const gefiltert = !!(fArt || fStatus === 'ungelesen');
const abschnitte = [{ id: 'alle', titel: 'Alle Benachrichtigungen', zahl: gefiltert ? zahl(R.gesamt) + ' von ' + zahl(R.alle) : zahl(R.alle), offen_standard: true,
  info: 'Gelesene Benachrichtigungen werden nach 90 Tagen automatisch entfernt. Welche Arten in der Glocke erscheinen, legst du unter Einstellungen › Benachrichtigungen fest.',
  inhalt: [
    { typ: 'filter', id: 'alle', label: 'Benachrichtigungen filtern', felder: [
      { typ: 'auswahl', name: 'art', label: 'Art', wert: fArt, optionen: [{ wert: '', text: 'Alle Arten' }].concat(arten) },
      { typ: 'auswahl', name: 'status', label: 'Status', wert: fStatus === 'ungelesen' ? 'ungelesen' : '', optionen: [{ wert: '', text: 'Alle' }, { wert: 'ungelesen', text: 'Nur ungelesene' }] }] },
    { typ: 'tabelle', id: 'alle', titel: 'Benachrichtigungen', spalten: [
      { schluessel: 'zeit', titel: 'Zeit', sortierbar: true }, { schluessel: 'art', titel: 'Art', sortierbar: true }, { schluessel: 'titel', titel: 'Benachrichtigung', sortierbar: true },
      { schluessel: 'status', titel: 'Status' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen, sortierung: { spalte: ['zeit', 'art', 'titel'].includes(so.spalte) ? so.spalte : 'zeit', richtung: so.richtung === 'auf' ? 'auf' : 'ab' },
      seite: (Number(R.seite) || 1) === Math.ceil(sW / 2) ? sW : (Number(R.seite) || 1) * 2 - 1, je_seite: JE, gesamt: Number(R.gesamt) || 0,
      leer: gefiltert ? 'Keine Benachrichtigungen für diese Auswahl.' : 'Noch keine Benachrichtigungen.' }] }];
// ---------- BA10: Ergebnisse ----------
const EG = ($input.first().json || {}).e || {};
const ARTEN = [['morgen_briefing', 'Briefing'], ['kundenueberblick', 'Kundenüberblick'], ['talents_wochen_briefing', 'KI-Analyse']];   // Migration 208 (eine Funktion „Briefing“, Stefan 06.11.2026): Name „Briefing“
const erWahl = /^[0-9]{1,12}$/.test(String((E.parameter || {}).er || '')) ? String(E.parameter.er) : '';
const ergebnisse = [];
for (const [a, name] of ARTEN) {
  const L = EG[a] && EG[a].ok === true && Array.isArray(EG[a].liste) ? EG[a].liste : [];
  for (const x of L) if (/^[0-9]{1,12}$/.test(String(x.id))) ergebnisse.push(Object.assign({ art_name: name }, x));
}
const hierE = extra => ({ seite: 'benachrichtigungen', parameter: Object.assign({}, filterParam, extra || {}), anker: 'a-ergebnisse' });
const datei = x => ({ seite: 'datei', parameter: { er: String(x.id) } });
abschnitte.push({ id: 'ergebnisse', titel: 'Ergebnisse', zahl: zahl(ergebnisse.length), offen_standard: !!erWahl,
  info: 'Der vollständige Text der letzten Morgen-Briefings, Kundenüberblicke und KI-Analysen nach Zeitplan (je Art bis zu 20, höchstens 180 Tage). Das PDF eines Kundenüberblicks lädt Ally aus dem Speicherort.',
  inhalt: [{ typ: 'liste', leer: 'Noch keine Ergebnisse. Sie erscheinen hier, sobald ein Morgen-Briefing, ein Kundenüberblick oder eine KI-Analyse nach Zeitplan erstellt wurde.',
    eintraege: ergebnisse.map(x => Object.assign({ fett: x.art_name, text: String(x.titel || ''), neben: String(x.zeit || ''), ziel: hierE({ er: String(x.id) }), ziel_text: 'Lesen' },
      x.datei ? { aktion: { text: 'PDF', label: 'PDF herunterladen: ' + String(x.titel || ''), ziel: datei(x) } } : {})) }] });
// Text eines Ergebnisses in Bausteine: Absätze; mehrzeilige Absätze mit kurzer erster Zeile = Überschrift und Liste (Zeilen ohne Spiegelstrich)
const bausteine = t => {
  const aus = [];
  for (const abs of String(t || '').split(/\n{2,}/)) {
    const z = abs.split('\n').map(x => x.trim()).filter(Boolean);
    if (!z.length) continue;
    if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; }
    let start = 0;
    if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); start = 1; }
    aus.push({ typ: 'liste', eintraege: z.slice(start).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) });
  }
  return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }];
};
const fenster = [];
const sel = erWahl ? ergebnisse.find(x => String(x.id) === erWahl) : null;
if (sel) fenster.push({ id: 'ergebnis', art: 'seitenfenster', offen: true, titel: String(sel.titel || sel.art_name), untertitel: sel.art_name + (sel.zeit ? ' · ' + String(sel.zeit) : ''),
  schliessen_ziel: hierE({}), inhalt: bausteine(sel.text).concat(sel.datei ? [{ typ: 'aktion', text: 'PDF herunterladen', label: 'PDF herunterladen: ' + String(sel.datei_name || sel.titel || ''), ziel: datei(sel) }] : []) });
return [{ json: { inhalt: { seite: kopf, ueberblick, abschnitte, fenster } } }];

// Parameter (ALLY 34, Benachrichtigungen, BA4b Stefan 20.10.2026): Sitzung, Filter (art = Schlüssel einer Art, status = alle | ungelesen), Seite der Tabelle.
const E = $input.first().json;
const P = E.parameter || {};
const art = /^[a-z0-9_]{1,40}$/.test(String(P.art || '')) ? String(P.art) : '';
const status = String(P.status || '') === 'ungelesen' ? 'ungelesen' : 'alle';
// Layout 12 (Plan 39): angezeigt werden 10 je Seite, die Datenbank blättert zu 20 – Seite n der Anzeige liegt auf Datenbank-Seite ceil(n/2)
const seite = Math.ceil(Math.max(1, Math.min(200000, Number((E.seiten || {}).alle) || 1)) / 2);
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify({ art, status }), seite] } }];
